<?php
namespace App\Http\Controllers\Api;
use App\Domain\Workplan\Models\{Workplan,WorkplanActivity,WorkplanProgressReport}; use App\Domain\Workplan\Services\WorkplanProgressService; use App\Http\Controllers\Controller; use App\Http\Requests\Workplan\{ReturnWorkplanProgressRequest,StoreWorkplanProgressReportRequest,SyncWorkplanIndicatorProgressRequest,UpdateWorkplanProgressReportRequest}; use App\Http\Resources\{WorkplanProgressDetailResource,WorkplanProgressListResource}; use Illuminate\Http\Request;
class WorkplanProgressController extends Controller { public function index(Request $r){$this->authorize('viewAny',WorkplanProgressReport::class);$q=WorkplanProgressReport::query()->with(['activity.department','activity.responsibleStaff'])->when($r->period,fn($q,$v)=>$q->where('period',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest();return WorkplanProgressListResource::collection($q->get());} public function matrix(Workplan $workplan){$this->authorize('view',$workplan);return response()->json(['data'=>$workplan->load('objectives.activities.department','objectives.activities.responsibleStaff')->objectives->flatMap->activities->map(fn($a)=>['id'=>$a->id,'code'=>$a->activity_code,'title'=>$a->title,'department'=>$a->department?->only(['id','name']),'responsible_staff'=>$a->responsibleStaff?->only(['id','full_name']),'reports'=>$a->progressReports()->get()->keyBy(fn($r)=>$r->period->value)->map(fn($r)=>['id'=>$r->id,'status'=>$r->status->value])])]);} public function show(WorkplanProgressReport $report){$this->authorize('view',$report);return new WorkplanProgressDetailResource($report->load(['activity.department','activity.responsibleStaff','indicators.indicator','evidence.uploadedBy','preparedBy','submittedBy','verifiedBy','returnedBy']));} public function create(StoreWorkplanProgressReportRequest $r,WorkplanActivity $activity,WorkplanProgressService $s){return (new WorkplanProgressDetailResource($s->create($activity,$r->validated('period'),$r->user())))->response()->setStatusCode(201);} public function update(UpdateWorkplanProgressReportRequest $r,WorkplanProgressReport $report,WorkplanProgressService $s){return new WorkplanProgressDetailResource($s->update($report,$r->validated(),$r->user()));} public function indicators(SyncWorkplanIndicatorProgressRequest $r,WorkplanProgressReport $report,WorkplanProgressService $s){return new WorkplanProgressDetailResource($s->syncIndicators($report,$r->validated('indicators'),$r->user()));} public function submit(Request $r,WorkplanProgressReport $report,WorkplanProgressService $s){return new WorkplanProgressDetailResource($s->submit($report,$r->user()));} public function verify(Request $r,WorkplanProgressReport $report,WorkplanProgressService $s){return new WorkplanProgressDetailResource($s->verify($report,$r->user()));} public function return(ReturnWorkplanProgressRequest $r,WorkplanProgressReport $report,WorkplanProgressService $s){return new WorkplanProgressDetailResource($s->return($report,$r->validated('return_reason'),$r->user()));}}
